input.content:
import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
const errors = [];
try {
  const page = await browser.newPage({ viewport: { width: 1440, height: 1000 }, deviceScaleFactor: 1 });
  page.on('pageerror', error => errors.push(`pageerror: ${error.message}`));
  page.on('console', message => { if (message.type() === 'error' && !message.text().includes('fonts.googleapis.com')) errors.push(`console: ${message.text()}`); });
  const home = await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'networkidle' });
  assert.equal(home.status(), 200, 'Verde index should load');
  const gameLink = page.getByRole('link', { name: /Bruma botánica/ });
  assert.equal(await gameLink.count(), 1, 'home should expose a single Bruma game link');
  await gameLink.click();
  await page.waitForURL('**/bruma-botanica.html');
  assert.equal(await page.title(), 'Bruma botánica · Verde');
  assert.equal(await page.locator('.memory-card').count(), 8);
  assert.equal(await page.locator('#roundValue').innerText(), '1 / 3');

  const first = page.locator('.memory-card').first();
  await first.focus();
  await page.keyboard.press('Enter');
  assert.equal(await first.getAttribute('aria-pressed'), 'true', 'Enter should reveal focused card');
  await page.keyboard.press('Tab');
  assert.equal(await page.evaluate(() => document.activeElement?.classList.contains('memory-card')), true, 'keyboard focus should stay in the board after reveal');
  await page.waitForTimeout(1100);
  assert.notEqual(await page.locator('#timeValue').innerText(), '00:00', 'timer should start on first move');
  await page.getByRole('button', { name: /Reiniciar/ }).click();
  assert.equal(await page.locator('#timeValue').innerText(), '00:00', 'restart should reset timer');
  assert.equal(await page.locator('#scoreValue').innerText(), '000', 'restart should reset score');

  async function solveRound(expectedRound) {
    const memory = new Map();
    let moves = 0;
    while (Number(await page.locator('#roundValue').locator('..').innerText().then(s => s.trim().split(/\s+/)[0])) === expectedRound && await page.locator('#victoryPanel').isHidden()) {
      assert.ok(moves++ < 80, `round ${expectedRound} should complete without hanging`);
      const hidden = page.locator('.memory-card[aria-pressed="false"]:not(:disabled)');
      if (!(await hidden.count())) break;
      const firstIndex = await page.locator('.memory-card').evaluateAll(cards => cards.findIndex(card => card.getAttribute('aria-pressed') === 'false' && !card.disabled));
      await page.locator('.memory-card').nth(firstIndex).click();
      const firstIcon = await page.locator('.memory-card').nth(firstIndex).locator('.card-face').innerText();
      const knownIndex = memory.get(firstIcon);
      const secondIndex = knownIndex !== undefined && knownIndex !== firstIndex && await page.locator('.memory-card').nth(knownIndex).getAttribute('aria-pressed') === 'false'
        ? knownIndex
        : await page.locator('.memory-card').evaluateAll(cards => cards.findIndex((card, index) => index !== Number(document.activeElement?.dataset?.index) && card.getAttribute('aria-pressed') === 'false' && !card.disabled));
      let partner = secondIndex;
      if (partner === firstIndex || partner < 0) {
        partner = await page.locator('.memory-card').evaluateAll(cards => {
          const first = cards.findIndex(card => card.classList.contains('is-revealed') && card.getAttribute('aria-pressed') === 'true');
          return cards.findIndex((card, index) => index !== first && card.getAttribute('aria-pressed') === 'false' && !card.disabled);
        });
      }
      assert.ok(partner >= 0, 'must have a second hidden card');
      await page.locator('.memory-card').nth(partner).click();
      const secondIcon = await page.locator('.memory-card').nth(partner).locator('.card-face').innerText();
      if (firstIcon !== secondIcon) {
        memory.set(firstIcon, firstIndex);
        memory.set(secondIcon, partner);
        await page.waitForTimeout(800);
      }
    }
    if (expectedRound < 3) await page.waitForFunction(round => Number(document.querySelector('#roundValue').textContent.trim().split('/')[0]) === round + 1, expectedRound, { timeout: 5000 });
  }
  for (let round = 1; round <= 3; round += 1) await solveRound(round);
  await page.getByText('¡Qué buena cosecha!').waitFor({ state: 'visible', timeout: 5000 });
  assert.equal(await page.locator('#progressBar').evaluate(el => el.style.width), '100%');
  assert.ok(Number(await page.locator('#scoreValue').innerText()) > 0, 'matches should award points');
  assert.equal(await page.locator('.memory-card').count(), 12, 'final round should show six pairs');
  await page.screenshot({ path: '/tmp/opencode/bruma-victoria.jpg', type: 'jpeg', quality: 90, fullPage: true });

  await page.getByRole('button', { name: /Jugar otra vez/ }).click();
  assert.equal(await page.locator('#roundValue').innerText(), '1 / 3', 'play again should reset round');
  assert.equal(await page.locator('.memory-card').count(), 8, 'play again should reset deck');

  const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
  mobile.on('pageerror', error => errors.push(`mobile pageerror: ${error.message}`));
  await mobile.goto('http://127.0.0.1:4173/bruma-botanica.html', { waitUntil: 'networkidle' });
  assert.equal(await mobile.locator('.memory-card').count(), 8);
  const dimensions = await mobile.evaluate(() => ({ width: innerWidth, scrollWidth: document.documentElement.scrollWidth, board: document.querySelector('#tablero').getBoundingClientRect().width }));
  assert.ok(dimensions.scrollWidth <= dimensions.width, `mobile layout must not overflow: ${JSON.stringify(dimensions)}`);
  await mobile.screenshot({ path: '/tmp/opencode/bruma-movil.jpg', type: 'jpeg', quality: 90, fullPage: true });
  assert.deepEqual(errors, [], `browser should be clean: ${errors.join('; ')}`);
  console.log(JSON.stringify({ ok: true, desktop: 'complete 3 rounds, scoring/timer/restart/keyboard passed', mobile: dimensions, screenshots: ['/tmp/opencode/bruma-victoria.jpg', '/tmp/opencode/bruma-movil.jpg'], errors }, null, 2));
  await mobile.close();
  await page.close();
} finally {
  await browser.close();
}

