async function solveRound(expectedRound) {
  const memory = new Map();
  let moves = 0;
  while (await page.locator('#roundValue').evaluate(el => Number(el.textContent.split('/')[0].trim())) === expectedRound && await page.locator('#victoryPanel').isHidden()) {
    assert.ok(moves++ < 100, `round ${expectedRound} should complete without hanging`);
    const cards = page.locator('.memory-card');
    const firstIndex = await cards.evaluateAll(all => all.findIndex(card => card.getAttribute('aria-pressed') === 'false' && !card.disabled));
    if (firstIndex < 0) break;
    await cards.nth(firstIndex).click();
    const firstIcon = await cards.nth(firstIndex).locator('.card-face').innerText();
    let partner = [...memory.entries()].find(([index, icon]) => icon === firstIcon
      && index !== firstIndex
      && page.locator('.memory-card').nth(index).getAttribute('aria-pressed').then(value => value === 'false')
      && page.locator('.memory-card').nth(index).isDisabled().then(disabled => !disabled))?.[0];
    if (partner === undefined) {
      const hidden = await cards.evaluateAll(all => all.map((card, index) => ({ index, hidden: card.getAttribute('aria-pressed') === 'false' && !card.disabled })));
      partner = hidden.find(card => card.index !== firstIndex && !memory.has(card.index))?.index;
      if (partner === undefined) partner = hidden.find(card => card.index !== firstIndex && card.hidden)?.index;
    }
    assert.ok(partner >= 0, 'must have a second hidden card');
    await cards.nth(partner).click();
    const secondIcon = await cards.nth(partner).locator('.card-face').innerText();
    memory.set(firstIndex, firstIcon);
    memory.set(partner, secondIcon);
